css:
.pattern-waves {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;

  background: #f8fafc;
}

.pattern-waves::before {
  content: "";
  position: absolute;
  inset: 0;

  background: repeating-radial-gradient(
    circle at 0% 50%,
    rgba(0, 0, 0, 0.04) 0px,
    rgba(0, 0, 0, 0.04) 2px,
    transparent 2px,
    transparent 30px
  );
}
